 10581→        let accumulated = '';
 10582→        function finish(success) {
 10583→          botBubble.classList.remove('ai-thinking');
 10584→          busy = false;
 10585→          sendBtn.disabled = false;
 10586→          msgInput.focus();
 10587→          if (success && accumulated) {
 10588→            // Add disclaimer to the response
 10589→            const responseWithDisclaimer = accumulated + AI_DISCLAIMER;
 10590→            botBubble.innerHTML = markdownToHTML(responseWithDisclaimer);
 10591→            
 10592→            chatHistory.push(
 10593→              { role: 'user', content: text },
 10594→              { role: 'assistant', content: accumulated }
 10595→            );
 10596→            if (chatHistory.length > 10) {
 10597→              chatHistory = chatHistory.slice(-10);
 10598→            }
 10599→          }
 10600→        }
 10601→
 10602→        fetch('https://assistant.safecast.org/chat', {
 10603→          method: 'POST',
 10604→          headers: { 'Content-Type': 'application/json' },
 10605→          body: JSON.stringify({
 10606→            message: text,
 10607→            history: chatHistory,
 10608→            map_context: getMapContext()
 10609→          }),
 10610→        }).then(response => {
 10611→          const reader = response.body.getReader();
 10612→          const decoder = new TextDecoder();
 10613→          let buffer = '';
 10614→
 10615→          function pump() {
 10616→            return reader.read().then(({ done, value }) => {
 10617→              if (done) { finish(true); return; }
 10618→
 10619→              buffer += decoder.decode(value, { stream: true });
 10620→              const lines = buffer.split('\n');
